# R golden fixtures for gaply_core's independent-samples t-test as an
# analysis (Research OS, Phase 4B-1, capability stats.analyze.independent_t).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_ttest_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R or of
# effectsize is copied into Gaply. Needs the CRAN package effectsize
# (approved for reference fixtures only, decision 67).
#
# Writes, next to this script: one synthetic data CSV per dataset
# (data_*.csv, a two-line '#' header, then `id,y,g`), golden.csv with R's
# answer for every case and variant, quantiles.csv with qt(0.975, df) over a
# grid of df, and cells_bits.csv with the IEEE 754 bits of every number R
# read. Every data file is written, READ BACK with read.csv(na.strings = "",
# g as character), and everything is computed on what was read.
#
# How a case maps onto Gaply's spec (decision 65):
#   * the group's levels are the distinct non-missing g, sorted with
#     sort(method = "radix"): code-point order, whatever the locale, which is
#     Gaply's order;
#   * the case names two levels by their 0-based INDEX in that order,
#     level_index1 and level_index2; R sets the factor's levels to exactly
#     those two, in that order, so group 1 is the first and every difference
#     is group 1 minus group 2, as in Gaply;
#   * missing_codes are values of y treated as missing (the outcome only).
#
# A row is left out for one reason, the first that applies, in this order:
# missing_group (g empty), other_level (g not one of the two), missing_outcome
# (y empty), missing_code (y a listed code). Gaply counts the same way.
#
# R calls (R and effectsize versions are written into golden.csv's header):
#   t.test(y ~ f, var.equal = TRUE / FALSE, conf.level = 0.95)
#     -> statistic, parameter (df), p.value, conf.int, stderr, estimate
#   effectsize::cohens_d(y ~ f, pooled_sd = TRUE / FALSE, ci = NULL)
#     -> Cohens_d (pooled_sd = FALSE divides by sqrt((s1^2 + s2^2) / 2))
#   mean, sd per group; sd_ratio = max(sd) / min(sd), NA when min(sd) is 0.
#
# A case Gaply refuses and R computes, or where R stops, is written as
# statistic `expected_refusal` with Gaply's code as the value, and
# `r_outcome` saying what R did (computes, or the start of R's error).
#
# Synthetic data only. No manuscript or data of anyone's is read.

suppressPackageStartupMessages(library(effectsize))

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) ifelse(is.na(x), "NA", sprintf("%.17g", as.numeric(x)))

rows <- list()
cell_bits <- list()
add <- function(case, data, l1, l2, codes, variant, statistic, value) {
  rows[[length(rows) + 1]] <<- data.frame(
    case = case, data = data, level_index1 = l1, level_index2 = l2,
    missing_codes = paste(codes, collapse = ";"), variant = variant,
    statistic = statistic, value = value, stringsAsFactors = FALSE)
}

# Write `df` (id, y, g), read it back, return what was read. The provenance
# header is prepended AFTER the read, so the lines R analysed are exactly the
# lines below the '#' header that the Rust test parses.
roundtrip <- function(df, name) {
  path <- file.path(here, name)
  write.csv(df, path, row.names = FALSE, quote = FALSE, na = "", fileEncoding = "UTF-8")
  back <- read.csv(path, na.strings = "", stringsAsFactors = FALSE, encoding = "UTF-8",
                   colClasses = c(id = "integer", y = "numeric", g = "character"))
  v <- back$y
  for (i in which(!is.na(v))) {
    b <- paste(as.character(writeBin(as.numeric(v[i]), raw(), size = 8, endian = "big")), collapse = "")
    cell_bits[[length(cell_bits) + 1]] <<- data.frame(data = name, row = i, bits = b, stringsAsFactors = FALSE)
  }
  body <- readLines(path, encoding = "UTF-8")
  writeLines(c(
    "# Synthetic data for gaply_core's t-test R golden fixtures (Research OS, Phase 4B-1).",
    "# Generated by /usr/local/bin/Rscript make_ttest_fixtures.R (do not edit by hand).",
    body), path, useBytes = TRUE)
  back
}

# The two chosen levels and the rows used, with the exclusion counts.
select_rows <- function(d, i1, i2, codes) {
  lv <- sort(unique(d$g[!is.na(d$g)]), method = "radix")
  chosen <- lv[c(i1, i2) + 1]
  reason <- ifelse(is.na(d$g), "missing_group",
            ifelse(!(d$g %in% chosen), "other_level",
            ifelse(is.na(d$y), "missing_outcome",
            ifelse(d$y %in% codes, "missing_code", "used"))))
  list(chosen = chosen, levels = lv, reason = reason,
       used = d[reason == "used", , drop = FALSE])
}

ttest_case <- function(case, name, d, i1 = 0, i2 = 1, codes = numeric(0), refusal = NULL) {
  s <- select_rows(d, i1, i2, codes)
  u <- s$used
  u$f <- factor(u$g, levels = s$chosen)
  for (variant in c("student", "welch")) {
    for (r in c("missing_group", "other_level", "missing_outcome", "missing_code")) {
      add(case, name, i1, i2, codes, variant, paste0("excluded_", r), as.character(sum(s$reason == r)))
    }
    add(case, name, i1, i2, codes, variant, "levels", as.character(length(s$levels)))
    if (!is.null(refusal)) {
      out <- tryCatch({
        t.test(y ~ f, data = u, var.equal = variant == "student")
        "computes"
      }, error = function(e) paste0("error: ", gsub("[,\n]", " ", conditionMessage(e))))
      add(case, name, i1, i2, codes, variant, "expected_refusal", refusal)
      add(case, name, i1, i2, codes, variant, "r_outcome", out)
      next
    }
    tt <- t.test(y ~ f, data = u, var.equal = variant == "student", conf.level = 0.95)
    d_r <- cohens_d(y ~ f, data = u, pooled_sd = variant == "student", ci = NULL)$Cohens_d
    g1 <- u$y[u$f == s$chosen[1]]
    g2 <- u$y[u$f == s$chosen[2]]
    sds <- c(sd(g1), sd(g2))
    stats <- list(
      t = unname(tt$statistic), df = unname(tt$parameter), p = tt$p.value,
      mean_difference = unname(tt$estimate[1] - tt$estimate[2]),
      se = tt$stderr, ci_lower = tt$conf.int[1], ci_upper = tt$conf.int[2],
      cohens_d = d_r,
      n1 = length(g1), n2 = length(g2), mean1 = mean(g1), mean2 = mean(g2),
      sd1 = sds[1], sd2 = sds[2],
      sd_ratio = if (min(sds) == 0) NA else max(sds) / min(sds))
    for (k in names(stats)) {
      v <- stats[[k]]
      add(case, name, i1, i2, codes, variant, k,
          if (k %in% c("n1", "n2")) as.character(v) else f17(v))
    }
  }
}

frame <- function(y, g) data.frame(id = seq_along(y), y = y, g = g, stringsAsFactors = FALSE)
two <- function(a, b, la = "a", lb = "b") frame(c(a, b), c(rep(la, length(a)), rep(lb, length(b))))

set.seed(20261018)

# 1. Two values per group, the smallest Gaply computes.
d <- roundtrip(two(c(4.25, 5.5), c(6.75, 9)), "data_n2.csv")
ttest_case("n2", "data_n2.csv", d)

# 2. Unequal n.
d <- roundtrip(two(round(rnorm(7, 10, 2), 3), round(rnorm(23, 12, 2), 3)), "data_unequal_n.csv")
ttest_case("unequal_n", "data_unequal_n.csv", d)

# 3. Unequal variances and n: Welch and Student differ.
d <- roundtrip(two(round(rnorm(15, 50, 1), 4), round(rnorm(40, 53, 10), 4)), "data_unequal_var.csv")
ttest_case("unequal_var", "data_unequal_var.csv", d)

# 4. Ties: integers 1 to 5.
d <- roundtrip(two(sample(1:5, 30, replace = TRUE), sample(1:5, 34, replace = TRUE)), "data_ties.csv")
ttest_case("ties", "data_ties.csv", d)

# 5. A 1e9 offset with an sd of 10: the means cancel to a small difference.
d <- roundtrip(two(1e9 + round(rnorm(50, 0, 10), 3), 1e9 + round(rnorm(60, 4, 10), 3)), "data_offset.csv")
ttest_case("offset_1e9", "data_offset.csv", d)

# 6. Heavy tails: Student t with 1.5 df.
d <- roundtrip(two(round(rt(40, 1.5), 5), round(rt(45, 1.5) + 1, 5)), "data_heavy_tail.csv")
ttest_case("heavy_tail", "data_heavy_tail.csv", d)

# 7. Negative values.
d <- roundtrip(two(round(rnorm(25, -500, 30), 2), round(rnorm(28, -480, 25), 2)), "data_negative.csv")
ttest_case("negative", "data_negative.csv", d)

# 8. 5,000 rows, the ingest's cap.
d <- roundtrip(two(round(rnorm(2400, 100, 15), 3), round(rnorm(2600, 101, 15), 3)), "data_large.csv")
ttest_case("large_5000", "data_large.csv", d)

# 9. One constant group: computed under both variants, as R does.
d <- roundtrip(two(rep(3.5, 10), round(rnorm(12, 5, 1), 3)), "data_one_constant.csv")
ttest_case("one_constant", "data_one_constant.csv", d)

# 10. Both groups constant: R stops; Gaply refuses with a code.
d <- roundtrip(two(rep(2, 6), rep(7, 8)), "data_both_constant.csv")
ttest_case("both_constant", "data_both_constant.csv", d, refusal = "stats.ttest.both_groups_constant")

# 11. A group of one: R's Student t computes it, Welch stops; Gaply refuses.
d <- roundtrip(two(c(3.1), round(rnorm(9, 4, 1), 3)), "data_group_of_one.csv")
ttest_case("group_of_one", "data_group_of_one.csv", d, refusal = "stats.ttest.group_too_small")

# 12. Three levels; two chosen, in both orders. Rows in the third are left out.
y <- round(c(rnorm(12, 20, 3), rnorm(10, 25, 3), rnorm(14, 22, 3)), 3)
g <- sample(c(rep("ctrl", 12), rep("dose_hi", 10), rep("dose_lo", 14)))
d <- roundtrip(frame(y, g), "data_three_levels.csv")
ttest_case("three_levels_0_2", "data_three_levels.csv", d, 0, 2)
ttest_case("three_levels_2_0", "data_three_levels.csv", d, 2, 0)

# 13. Missing outcomes, missing groups, and both in one row.
y <- round(rnorm(40, 10, 3), 3)
g <- rep(c("a", "b"), 20)
y[c(3, 8, 15, 22)] <- NA
g[c(5, 15, 30)] <- NA
d <- roundtrip(frame(y, g), "data_missing.csv")
ttest_case("missing", "data_missing.csv", d)

# 14. -99 as a code in the outcome: ticked, and not ticked.
y <- round(rnorm(36, 30, 5), 2)
y[c(2, 9, 17, 25, 33)] <- -99
g <- rep(c("pre", "post"), 18)
g[9] <- NA
d <- roundtrip(frame(y, g), "data_coded.csv")
ttest_case("coded_99_ticked", "data_coded.csv", d, codes = -99)
ttest_case("coded_99_not_ticked", "data_coded.csv", d)

# 15. Code-point order: "B" sorts before "a", so group 1 is "B".
d <- roundtrip(two(round(rnorm(11, 5, 1), 3), round(rnorm(13, 6, 1), 3), "a", "B"), "data_codepoint.csv")
ttest_case("codepoint_order", "data_codepoint.csv", d)

# 16. Integer group codes, read as levels "1" and "2".
d <- roundtrip(two(round(rnorm(16, 0, 1), 4), round(rnorm(18, 0.5, 1), 4), "1", "2"), "data_numeric_group.csv")
ttest_case("numeric_group", "data_numeric_group.csv", d)

all <- do.call(rbind, rows)
header <- c(
  "# R golden values for gaply_core's independent-samples t-test (Research OS, Phase 4B-1).",
  "# Generated by /usr/local/bin/Rscript make_ttest_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; effectsize %s; set.seed(20261018).", R.version.string, R.version$arch,
          as.character(packageVersion("effectsize"))),
  "# t.test(y ~ f, var.equal = TRUE/FALSE, conf.level = 0.95); effectsize::cohens_d(y ~ f, pooled_sd = TRUE/FALSE, ci = NULL); numbers %.17g; NA where R gives none.")
out <- file.path(here, "golden.csv")
writeLines(header, out)
write.table(all, out, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)

grid <- c(1, 1.5, 2, 2.5, 3, 3.7, 4, 5, 6, 7, 8, 9, 10, 12.25, 15, 17.3456, 20, 25, 30, 40, 50,
          75, 100, 150.5, 200, 500, 1000, 2500, 4998, 1e4, 1e5, 1e6, 1e7)
qf <- file.path(here, "quantiles.csv")
writeLines(c(
  "# R's qt(0.975, df), the 95% interval's quantile, for gaply_core's t-test (Research OS, Phase 4B-1).",
  "# Generated by /usr/local/bin/Rscript make_ttest_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s.", R.version.string, R.version$arch)), qf)
write.table(data.frame(df = f17(grid), q = f17(qt(0.975, grid))), qf, sep = ",", quote = FALSE,
            row.names = FALSE, append = TRUE)

bits <- do.call(rbind, cell_bits)
bf <- file.path(here, "cells_bits.csv")
writeLines(c(
  "# The IEEE 754 bits of every y R read, for gaply_core's t-test golden fixtures (Research OS, Phase 4B-1).",
  "# Generated by /usr/local/bin/Rscript make_ttest_fixtures.R (do not edit by hand)."), bf)
write.table(bits, bf, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)

cat(sprintf("wrote %d golden rows for %d cases, %d quantiles, and the bits of %d cells\n",
            nrow(all), length(unique(all$case)), length(grid), nrow(bits)))
